mapper.select:
select inflow.cashflow_id, 1 seq_num, cc.contract_number, c.cashflow_id, c.contract_id, c.cf_item, c.cf_type, c.cf_direction, c.cf_status, c.times, (select h.description from hls_cashflow_item h where h.cf_item = c.cf_item)cashflow_id_n, c.due_date, c.due_amount, case when c.bp_id is null then ( select hbm.bp_id from prj_project_bp ppb,hls_bp_master hbm where ppb.project_id = cc.project_id and ppb.bp_type = 'TENANT' and ppb.bp_id = hbm.bp_id and rownum=1 ) else c.bp_id end bp_id, case when c.bp_id is null then ( select hbm.bp_name from prj_project_bp ppb,hls_bp_master hbm where ppb.project_id = cc.project_id and ppb.bp_type = 'TENANT' and ppb.bp_id = hbm.bp_id and rownum=1 ) else (select hbm.bp_name from hls_bp_master hbm where hbm.bp_id = c.bp_id) end bp_id_n, hba.bank_account_id, case when hba.bank_account_name is null then ( select hbma.bank_account_name from prj_project_bp ppb,hls_bp_master_bank_account hbma where ppb.project_id = cc.project_id and ppb.bp_type = 'TENANT' and ppb.bank_account_id = hbma.bank_account_id and rownum=1 ) else hba.bank_account_name end bank_account_name, case when hba.bank_account_num is null then ( select hbma.bank_account_num from prj_project_bp ppb,hls_bp_master_bank_account hbma where ppb.project_id = cc.project_id and ppb.bp_type = 'TENANT' and ppb.bank_account_id = hbma.bank_account_id and rownum=1 ) else hba.bank_account_num end bank_account_num, case when hba.bank_full_name is null then ( select hbma.bank_full_name from prj_project_bp ppb,hls_bp_master_bank_account hbma where ppb.project_id = cc.project_id and ppb.bp_type = 'TENANT' and ppb.bank_account_id = hbma.bank_account_id and rownum=1 ) else hba.bank_full_name end bank_branch_name, c.payment_method, s.MEANING payment_method_n, c.FUNDING_PLAN_STATUS from con_contract_cashflow c left join sys_code_value_b_v s on s.CODE = 'CSH.PAYMENT_METHOD' and c.payment_method = s.code_value left join hls_bp_master_bank_account hba on hba.bank_account_id = c.bank_account_id , con_contract cc, hls_funding_plan_inflow inflow
c.contract_id = cc.contract_id and c.cf_direction = 'INFLOW' and inflow.cashflow_id = c.cashflow_id
and inflow.funding_plan_id = #{fundingPlanId}
